document.getElementById('craftAxe').addEventListener('click',()=>craft('axe'));document.getElementById('craftPick').addEventListener('click',()=>craft('pick'));document.getElementById('craftMeal').addEventListener('click',()=>craft('meal'));document.getElementById('craftCamp').addEventListener('click',()=>craft('camp'));document.getElementById('evolveBtn').addEventListener('click',evolve);document.getElementById('helpBtn').addEventListener('click',()=>document.getElementById('helpModal').classList.add('open'));document.getElementById('closeHelp').addEventListener('click',()=>document.getElementById('helpModal').classList.remove('open'));document.getElementById('startBtn').addEventListener('click',()=>document.getElementById('helpModal').classList.remove('open'));document.getElementById('soundBtn').addEventListener('click',()=>notify('The forest is peaceful. Ambient sounds coming soon.'));
