function resize(){let r=area.getBoundingClientRect();ratio=Math.min(devicePixelRatio||1,2);canvas.width=r.width*ratio;canvas.height=r.height*ratio;ctx.setTransform(ratio,0,0,ratio,0,0);let mapW=(W+H)*cw/2,mapH=(W+H)*ch/2,s=Math.min(r.width/(mapW+30),r.height/(mapH+15));cw=60*s;ch=32*s;mapW=(W+H)*cw/2;mapH=(W+H)*ch/2;ox=(r.width-mapW)/2+H*cw/2;oy=(r.height-mapH)/2+ch*.8;draw()}
function point(x,y){return{x:ox+(x-y)*cw/2,y:oy+(x+y)*ch/2}}
function poly(points,fill,stroke){ctx.beginPath();ctx.moveTo(...points[0]);points.slice(1).forEach(p=>ctx.lineTo(...p));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
function diamond(x,y,w,h,color,stroke){poly([[x,y-h/2],[x+w/2,y],[x,y+h/2],[x-w/2,y]],color,stroke)}
function tree(x,y,s){ctx.save();ctx.translate(x,y);poly([[-s*.09,-s*.05],[-s*.01,-s*.08],[s*.02,s*.35],[-s*.1,s*.33]],'#765337');poly([[-s*.01,-s*.08],[s*.08,-s*.11],[s*.12,s*.30],[s*.02,s*.35]],'#65472f');diamond(0,-s*.04,s*.45,s*.2,'#315a39');diamond(-s*.06,-s*.3,s*.48,s*.3,'#467849');diamond(s*.08,-s*.48,s*.42,s*.31,'#598951');diamond(-s*.19,-s*.42,s*.28,s*.22,'#6a9a58');diamond(s*.17,-s*.32,s*.27,s*.21,'#3b7044');ctx.restore()}
function rock(x,y,s){ctx.save();ctx.translate(x,y);diamond(0,0,s*.56,s*.25,'#65746b');poly([[-s*.26,-s*.02],[-s*.16,-s*.23],[s*.04,-s*.29],[s*.24,-s*.14],[s*.25,s*.02],[0,s*.1]],'#78877a','#ffffff18');poly([[-s*.16,-s*.23],[s*.04,-s*.29],[s*.24,-s*.14],[s*.02,-s*.1]],'#9aa494');ctx.restore()}
function plant(x,y,s,node){ctx.save();ctx.translate(x,y);if(node==='berry'){diamond(0,s*.05,s*.44,s*.18,'#315a38');ctx.fillStyle='#477848';ctx.beginPath();ctx.arc(-s*.11,-s*.1,s*.2,0,7);ctx.arc(s*.11,-s*.13,s*.2,0,7);ctx.fill();ctx.fillStyle='#cf6681';[[-.12,-.15],[.09,-.21],[.18,-.07],[-.03,-.03]].forEach(([a,b])=>{ctx.beginPath();ctx.arc(a*s,b*s,s*.045,0,7);ctx.fill()})}else if(node==='fiber'){ctx.strokeStyle='#b9bd6c';ctx.lineWidth=2;for(let i=-2;i<3;i++){ctx.beginPath();ctx.moveTo(i*3,3);ctx.quadraticCurveTo(i*5,-9,i*4-2,-14-Math.abs(i));ctx.stroke()}diamond(0,3,s*.37,s*.12,'#63874d')}else{diamond(0,1,s*.43,s*.17,'#5d886d');poly([[-s*.1,0],[-s*.07,-s*.34],[0,-s*.48],[s*.1,-s*.31],[s*.12,0]],'#80dfcf','#d5fff080');poly([[0,-s*.47],[s*.1,-s*.31],[s*.12,0],[0,0]],'#47a99b')}ctx.restore()}
function player(x,y){ctx.save();ctx.translate(x,y);ctx.fillStyle='#10231d55';ctx.beginPath();ctx.ellipse(0,5,12,5,0,0,7);ctx.fill();poly([[-9,-9],[0,-5],[9,-9],[0,-13]],'#9bcf78');poly([[-9,-9],[0,-5],[0,1],[-9,-3]],'#47795d');poly([[0,-5],[9,-9],[9,-3],[0,1]],'#355c4b');ctx.fillStyle='#d5ad83';ctx.fillRect(-5,-28,10,12);ctx.fillStyle='#513e32';ctx.fillRect(-6,-30,12,5);ctx.fillStyle='#f1d5b2';ctx.fillRect(-4,-23,2,2);ctx.fillRect(2,-23,2,2);poly([[-7,-16],[0,-12],[7,-16],[0,-20]],'#d27d59');poly([[-7,-16],[0,-12],[0,-4],[-7,-8]],'#638f59');poly([[0,-12],[7,-16],[7,-8],[0,-4]],'#456d50');ctx.fillStyle='#b8845b';ctx.fillRect(-6,-5,4,5);ctx.fillRect(2,-5,4,5);ctx.restore()}
function draw(){if(!canvas.width)return;let r=area.getBoundingClientRect(),w=r.width,h=r.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#9ac99c';ctx.fillRect(0,0,w,h);let g=ctx.createRadialGradient(w*.52,h*.45,10,w*.52,h*.45,w*.72);g.addColorStop(0,'#c7dfa14a');g.addColorStop(1,'#426d5230');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);let order=[];for(let y=0;y<H;y++)for(let x=0;x<W;x++)order.push([x,y]);order.sort((a,b)=>a[0]+a[1]-b[0]-b[1]);for(let [x,y] of order){let p=point(x,y),t=tiles[y][x],colors=['#72975e','#789b61','#83a765','#6f925b','#87a96a'];diamond(p.x,p.y,cw,ch,colors[Math.floor(t.variation*5)],'#ffffff0c');if(t.type==='water'){diamond(p.x,p.y,cw,ch,'#5eaaa2','#d3eee533');ctx.fillStyle='#d8fff033';ctx.fillRect(p.x-6,p.y-1,10,1)}else if(t.type==='sand')diamond(p.x,p.y,cw,ch,'#c2b57c','#ffffff0a');if(state.selected?.x===x&&state.selected.y===y)diamond(p.x,p.y,cw*.92,ch*.9,'#efff8d36','#eeff9b');if(t.node){let s=cw*.62;ctx.fillStyle='#253b2d38';ctx.beginPath();ctx.ellipse(p.x,p.y+ch*.19,s*.47,s*.19,0,0,7);ctx.fill();if(t.node==='tree')tree(p.x,p.y+ch*.06,s);else if(t.node==='rock')rock(p.x,p.y+ch*.06,s);else plant(p.x,p.y+ch*.06,s,t.node)}if(state.player.x===x&&state.player.y===y)player(p.x,p.y+ch*.05)}if(state.selected){let t=state.selected,d=Math.abs(t.x-state.player.x)+Math.abs(t.y-state.player.y);if(d<=2&&tiles[t.y]?.[t.x]?.node){let p=point(t.x,t.y),txt='E · Gather';ctx.font=`${Math.max(10,cw*.2)}px sans-serif`;ctx.textAlign='center';ctx.lineWidth=3;ctx.strokeStyle='#e7f2c8';ctx.fillStyle='#14251e';ctx.strokeText(txt,p.x,p.y-ch*.9);ctx.fillText(txt,p.x,p.y-ch*.9)}}}
function nearby(){let best=null,dist=99;for(let y=Math.max(0,state.player.y-2);y<=Math.min(H-1,state.player.y+2);y++)for(let x=Math.max(0,state.player.x-2);x<=Math.min(W-1,state.player.x+2);x++){let d=Math.abs(x-state.player.x)+Math.abs(y-state.player.y);if(d<=2&&tiles[y][x].node&&d<dist){best={x,y};dist=d}}return best}
function notify(msg){let el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function gainXP(n){state.xp+=n;while(state.xp>=state.level*30){state.xp-=state.level*30;state.level++;state.maxHp+=8;state.hp=Math.min(state.maxHp,state.hp+18);notify(`Level up! You reached level ${state.level}.`)}}
function gather(target){target=target||state.selected||nearby();if(!target)return notify('Nothing nearby to gather.');if(Math.abs(target.x-state.player.x)+Math.abs(target.y-state.player.y)>2)return notify('Move closer to gather that.');let t=tiles[target.y]?.[target.x];if(!t?.node)return notify('There is nothing to gather here.');let n=t.node;if(n==='tree'){let a=state.tools.axe?3:2;state.bag.wood+=a;if(state.tools.axe)state.bag.fiber++;state.essence++;notify(`+${a} wood${state.tools.axe?' · +1 fiber':''} · +1 essence`)}else if(n==='rock'){let a=state.tools.pick?3:2;state.bag.stone+=a;if(state.tools.pick&&rand(target.x,target.y)>.45)state.bag.crystal++;notify(`+${a} stone${state.tools.pick?' · chance of essence':''}`)}else if(n==='berry'){state.bag.berry+=2;notify('+2 wildberries · good for a quick bite')}else if(n==='fiber'){state.bag.fiber+=2;notify('+2 wild fiber')}else{state.bag.crystal++;state.essence+=2;notify('+1 wild essence · +2 essence')}t.node=null;gainXP(9);state.hunger=Math.max(0,state.hunger-1);render();draw()}
function move(dx,dy){if(performance.now()<state.moveTimer)return;state.moveTimer=performance.now()+125;let x=Math.max(0,Math.min(W-1,state.player.x+dx)),y=Math.max(0,Math.min(H-1,state.player.y+dy));if(tiles[y][x].type==='water')return notify('The deep water is impassable.');state.player.x=x;state.player.y=y;state.selected={x,y};draw()}

function quests(){let list=[['Gather your first resources',state.bag.wood+state.bag.stone+state.bag.berry+state.bag.fiber>0,'Collect from trees, stones, or berry bushes.'],['Craft a survival tool',state.tools.axe||state.tools.pick,'A hatchet or pick will help you thrive.'],['Find something to eat',state.bag.berry>0||state.hunger>90,'Gather wildberries to keep your strength.'],['Awaken your roots',state.age>1,'Collect resources to begin evolving.']];document.getElementById('quests').innerHTML=list.map(q=>`<div class="quest ${q[1]?'done':''}"><span class="check">${q[1]?'✓':''}</span><div class="qtext"><b>${q[0]}</b>${q[2]}</div></div>`).join('')}
function render(){let b=state.bag,icons={wood:'🪵',stone:'🪨',berry:'🫐',fiber:'🌾'},labels={wood:'Wood',stone:'Stone',berry:'Berries',fiber:'Fiber'};document.getElementById('inventory').innerHTML=types.map(t=>`<div class="slot"><span class="emoji">${icons[t]}</span><span class="label">${labels[t]}</span><span class="qty">${b[t]}</span></div>`).join('');document.getElementById('bagCount').textContent=`${Object.values(b).reduce((a,v)=>a+v,0)} / 8`;document.getElementById('essenceNum').textContent=state.essence+b.crystal;document.getElementById('healthNum').textContent=`${Math.ceil(state.hp)} / ${state.maxHp}`;document.getElementById('healthFill').style.width=`${Math.max(0,state.hp/state.maxHp*100)}%`;document.getElementById('hungerNum').textContent=`${Math.ceil(state.hunger)} / 100`;document.getElementById('hungerFill').style.width=`${state.hunger}%`;document.getElementById('xpFill').style.width=`${state.xp/(state.level*30)*100}%`;document.getElementById('levelText').textContent=`LEVEL ${state.level} · ${state.age===1?'WAYFARER':state.age===2?'ROOTBOUND':'WILDSHAPER'}`;document.getElementById('playerTitle').textContent=state.age===1?'Newcomer':state.age===2?'Rootbound':'Wildshaper';document.getElementById('avatar').textContent=state.age===1?'🧑🏻‍🌾':state.age===2?'🧝🏽':'🧙🏽';document.getElementById('ageText').textContent=`AGE ${['I','II','III'][state.age-1]}`;document.getElementById('craftAxe').disabled=!(b.wood>=4&&b.stone>=2&&!state.tools.axe);document.getElementById('craftPick').disabled=!(b.wood>=3&&b.stone>=3&&!state.tools.pick);document.getElementById('craftCamp').disabled=state.hp>=state.maxHp&&state.hunger>85;document.getElementById('craftMeal').disabled=b.berry<2||state.hunger>95;let req=state.age===1?{wood:8,stone:6,berry:3}:state.age===2?{wood:14,stone:12,berry:7,crystal:3}:null,ready=req&&Object.entries(req).every(([k,v])=>b[k]>=v);document.getElementById('evolveBtn').disabled=!ready;document.getElementById('evolveBtn').textContent=state.age>=3?'✧  FRONTIER MASTERED':'✧  AWAKEN YOUR ROOTS';document.getElementById('evolveCaption').innerHTML=state.age===1?'Gather 8 wood, 6 stone & 3 wildberries<br>to kindle your first evolution.':state.age===2?'Gather 14 wood, 12 stone, 7 berries & 3 essence<br>to enter the final age.':'You have become one with the wilds.';quests()}
function craft(k){let b=state.bag;if(k==='axe'&&b.wood>=4&&b.stone>=2&&!state.tools.axe){b.wood-=4;b.stone-=2;state.tools.axe=true;notify('Stone Hatchet crafted! Trees now yield more.')}else if(k==='pick'&&b.wood>=3&&b.stone>=3&&!state.tools.pick){b.wood-=3;b.stone-=3;state.tools.pick=true;notify('Trail Pick crafted! Rocks may reveal essence.')}else if(k==='meal'&&b.berry>=2&&state.hunger<=95){b.berry-=2;state.hunger=Math.min(100,state.hunger+30);state.hp=Math.min(state.maxHp,state.hp+5);notify('A nourishing meal restores 30 satiety.')}else if(k==='camp'){state.hp=Math.min(state.maxHp,state.hp+35);state.hunger=Math.min(100,state.hunger+24);notify('You rest by the campfire. Strength returns.')}render()}
function evolve(){if(state.age>=3)return;let req=state.age===1?{wood:8,stone:6,berry:3}:{wood:14,stone:12,berry:7,crystal:3};if(!Object.entries(req).every(([k,v])=>state.bag[k]>=v))return;Object.entries(req).forEach(([k,v])=>state.bag[k]-=v);state.age++;state.maxHp+=25;state.hp=state.maxHp;state.essence+=8;gainXP(40);notify(state.age===2?'Evolution awakened! You are Rootbound.':'Final evolution! The wilds answer your call.');render()}
function tick(){state.gameTime++;state.clock+=.035;if(state.clock>=20){state.clock=6;state.day++}state.hunger=Math.max(0,state.hunger-.004);if(state.hunger===0&&state.gameTime%8===0)state.hp=Math.max(1,state.hp-.4);if(state.hunger>50&&state.hp<state.maxHp&&state.gameTime%12===0)state.hp=Math.min(state.maxHp,state.hp+.2);let hour=Math.floor(state.clock),phase=hour<10?'MORNING':hour<14?'NOON':hour<18?'AFTERNOON':'DUSK';document.getElementById('dayLabel').textContent=`${hour>=18?'☾':'☀'} DAY ${state.day} · ${phase}`;document.getElementById('weatherText').textContent=hour>=18?'The forest grows quiet':'A good day to explore';if(state.gameTime%15===0)render();if(state.gameTime%12===0)draw()}
makeWorld();resize();render();window.addEventListener('resize',resize);setInterval(tick,1000);
