function drawHero(x,y){ctx.save();ctx.translate(x,y);ctx.fillStyle='#274b35';ctx.beginPath();ctx.ellipse(0,2,cw*.17,ch*.13,0,0,7);ctx.fill();ctx.fillStyle=s.age===1?'#795a3a':s.age===2?'#687a42':'#4b7953';ctx.beginPath();ctx.roundRect(-cw*.12,-ch*.76,cw*.24,ch*.68,5);ctx.fill();ctx.fillStyle='#e9bf91';ctx.beginPath();ctx.arc(0,-ch*.88,cw*.105,0,7);ctx.fill();ctx.fillStyle='#405d32';ctx.beginPath();ctx.arc(0,-ch*.98,cw*.13,Math.PI,0);ctx.fill();ctx.restore()}
