 function update(){const all=Object.keys(s.bag).reduce((a,k)=>a+s.bag[k],0);$('count').textContent=`${all} gathered`;$('bag').innerHTML=Object.entries(label).map(([k,v])=>`<div class="slot" title="${v[1]}">${v[0]}<small>${s.bag[k]}</small><em>${v[1]}</em></div>`).join('');$('ess').textContent=s.ess;$('hpv').textContent=`${Math.ceil(s.hp)} / ${s.max}`;$('foodv').textContent=`${Math.ceil(s.hunger)} / 100`;$('hp').style.width=`${100*s.hp/s.max}%`;$('food').style.width=`${s.hunger}%`;$('xp').style.width=`${100*s.xp/(s.level*30)}%`;$('lvl').textContent=`LEVEL ${s.level} · ${s.age===1?'WAYFARER':s.age===2?'ROOTBOUND':'WILDSHAPER'}`;$('age').textContent=['AGE I','AGE II','AGE III'][s.age-1];$('day').textContent=`${s.time<18?'☀':'☾'} DAY ${s.day} · ${s.time<6?'DAWN':s.time<12?'MORNING':s.time<18?'AFTERNOON':'NIGHT'}`;
 $('axe').disabled=s.tools.axe||s.bag.wood<4||s.bag.stone<2;$('pick').disabled=s.tools.pick||s.bag.wood<3||s.bag.stone<3;$('evolve').disabled=!canEvolve();const needs=[{wood:8,stone:6,berry:3},{wood:16,stone:12,berry:6,fiber:5},{wood:24,stone:18,berry:8,fiber:8,crystal:4}][s.age-1];$('cap').innerHTML=s.age===3?'The Verdant Wilds are yours. Keep gathering, crafting and surviving.':`Gather ${Object.entries(needs).map(([k,n])=>`${n} ${k==='berry'?'wildberries':k}`).join(', ')}<br>to kindle your ${s.age===1?'first':'final'} evolution.`;
 const qs=[['Gather 8 wood',s.bag.wood>=8],['Gather 6 stone',s.bag.stone>=6],['Collect wildberries',s.bag.berry>=3],['Craft a field tool',s.tools.axe||s.tools.pick],['Awaken your roots',s.age>1]];$('quests').innerHTML=qs.map(([t,d])=>`<div class="quest ${d?'done':''}">${d?'✓':'○'} ${t}</div>`).join('')}
