 function craft(kind){if(kind==='axe'||kind==='pick'){const req=kind==='axe'?{wood:4,stone:2}:{wood:3,stone:3};if(s.tools[kind]||!Object.entries(req).every(([k,n])=>s.bag[k]>=n))return say('Gather the materials shown first.');for(const[k,n]of Object.entries(req))s.bag[k]-=n;s.tools[kind]=true;say(kind==='axe'?'Stone Hatchet crafted! Trees yield more wood.':'Trail Pick crafted! Rocks yield more stone.');gainXP(12)}else if(kind==='camp'){s.hp=Math.min(s.max,s.hp+32);s.hunger=Math.min(100,s.hunger+16);s.time=(s.time+2)%24;if(s.time<2)s.day++;say('You rest by the fire. Feeling restored.')}else if(kind==='meal'){if(s.bag.berry<2)return say('You need 2 wildberries to make a trail meal.');s.bag.berry-=2;s.hunger=Math.min(100,s.hunger+30);gainXP(4);say('Trail meal eaten. Satiety restored.')}update()}
