 function harvest(x,y){if(x<0||y<0||x>=N||y>=N)return;const cell=world[y][x];if(!cell.node)return say('Nothing left to gather here.');if(dist(s,{x,y})>1)return say('Move closer to gather.');const n=cell.node;let key=n==='tree'?'wood':n==='rock'?'stone':n==='berry'?'berry':n==='fiber'?'fiber':'crystal';let amount=n==='tree'?(s.tools.axe?3:2):n==='rock'?(s.tools.pick?3:2):n==='crystal'?1:n==='berry'?2:2;s.bag[key]+=amount;if(n==='crystal')s.ess++;cell.node=null;cell.regrow=Date.now()+18000;gainXP(n==='crystal'?12:8);s.hunger=Math.max(0,s.hunger-1);say(`+${amount} ${key}${n==='crystal'?' · +1 essence':''}`);update()}
 function gather(){const n=nearest();if(!n)return say('No resources nearby. Explore the wilds!');if(n.d<=1)harvest(n.x,n.y);else{s.target={x:n.x,y:n.y,harvest:true};say('Heading to the nearest resource…')}}
 function autoStep(){if(!s.target)return;const t=s.target,done=p=>t.harvest?dist(p,t)<=1:p.x===t.x&&p.y===t.y;if(done(s)){if(t.harvest)harvest(t.x,t.y);s.target=null;return}const queue=[{x:s.x,y:s.y,first:null}],seen=new Set([`${s.x},${s.y}`]);let step=null;for(let i=0;i<queue.length&&!step;i++){const p=queue[i];for(const[dx,dy]of [[0,-1],[1,0],[0,1],[-1,0]]){const q={x:p.x+dx,y:p.y+dy},id=`${q.x},${q.y}`;if(q.x<0||q.y<0||q.x>=N||q.y>=N||world[q.y][q.x].type==='water'||seen.has(id))continue;const first=p.first||q;if(done(q)){step=first;break}seen.add(id);queue.push({...q,first})}}if(step){s.x=step.x;s.y=step.y;if(done(s)){if(t.harvest)harvest(t.x,t.y);s.target=null}}else{s.target=null;say('No clear path.')}}
 function move(dx,dy){if(Date.now()-s.moveAt<125)return;s.moveAt=Date.now();s.target=null;const x=s.x+dx,y=s.y+dy;if(x<0||y<0||x>=N||y>=N||world[y][x].type==='water')return;s.x=x;s.y=y;if(s.target&&dist(s,s.target)<=1){const{x:tx,y:ty}=s.target;s.target=null;harvest(tx,ty)}draw()}
